CREATE TABLE IF NOT EXISTS user_quick_link_preferences(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,user_email TEXT NOT NULL,module_href TEXT NOT NULL,visit_count INTEGER NOT NULL DEFAULT 0,last_used_at TEXT,pinned INTEGER NOT NULL DEFAULT 0 CHECK(pinned IN(0,1)),hidden INTEGER NOT NULL DEFAULT 0 CHECK(hidden IN(0,1)),updated_at TEXT NOT NULL,UNIQUE(organization_id,property_id,user_email,module_href));
CREATE TABLE IF NOT EXISTS adoption_metric_events(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,property_id TEXT NOT NULL,metric_key TEXT NOT NULL,numeric_value REAL NOT NULL,unit TEXT NOT NULL,source_table TEXT NOT NULL,source_record_id TEXT NOT NULL,occurred_at TEXT NOT NULL,dimensions_json TEXT NOT NULL,UNIQUE(organization_id,property_id,metric_key,source_table,source_record_id));
CREATE INDEX IF NOT EXISTS quick_link_profile_idx ON user_quick_link_preferences(organization_id,property_id,user_email,pinned,hidden,last_used_at);
CREATE INDEX IF NOT EXISTS adoption_metric_scope_idx ON adoption_metric_events(organization_id,property_id,metric_key,occurred_at);
